"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["82030"],{92102(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>l,frontMatter:()=>h,contentTitle:()=>p,toc:()=>d,assets:()=>c});var a=JSON.parse('{"id":"nhcx/v1/api/biometric/endpoints/biometric-hcx-abha-biometric-auth-init","title":"Submit the biometric auth init","description":"Starts a fingerprint or iris authentication of a PMJAY beneficiary against the ABHA registry and returns the txnId the verify call needs.","source":"@site/docs/nhcx/v1/api/biometric/endpoints/biometric-hcx-abha-biometric-auth-init.mdx","sourceDirName":"nhcx/v1/api/biometric/endpoints","slug":"/nhcx/v1/api/biometric/endpoints/biometric-hcx-abha-biometric-auth-init","permalink":"/docs/pr-29/docs/nhcx/v1/api/biometric/endpoints/biometric-hcx-abha-biometric-auth-init","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Submit the biometric auth init","sidebar_label":"Submit the biometric auth init","sidebar_class_name":"api-method api-method--post","description":"Starts a fingerprint or iris authentication of a PMJAY beneficiary against the ABHA registry and returns the txnId the verify call needs.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-biometric.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Overview","permalink":"/docs/pr-29/docs/nhcx/v1/api/biometric/"},"next":{"title":"Submit the biometric auth verify","permalink":"/docs/pr-29/docs/nhcx/v1/api/biometric/endpoints/biometric-hcx-abha-biometric-auth-verify"}}'),i=n(62540),r=n(43023),s=n(85030),o=JSON.parse('{"id":"biometric_hcx_abha_biometric_auth_init","module":"ABHA biometric authentication","moduleId":"biometric","kind":"operation","method":"POST","path":"/hcx/abha/biometric/auth/init","server":"https://apisbx.abdm.gov.in","servers":[{"url":"https://apisbx.abdm.gov.in","description":"Sandbox."}],"summary":"Biometric auth init","title":"Submit the biometric auth init","description":"Starts a fingerprint or iris authentication of a PMJAY beneficiary against the ABHA registry and returns the `txnId` the verify call needs.\\n\\n### Business purpose\\n\\nPMJAY requires proof that the beneficiary was physically present. A hospital proves it by authenticating them against their ABHA, biometrically, and the user token that results rides on the eligibility check, the pre-authorisation and the claim. A request without it, and without the consent form that stands in for it, is refused by name. These are ABDM calls built for the PMJAY payer, not NHCX calls: no JWE and no callbacks.\\n\\n### When to use\\n\\nUse it at the desk while the beneficiary is present: at admission, at discharge and at every visit of a cyclic case. `scope` picks fingerprint or iris. Face has its own calls, starting with `Face auth init`.\\n\\n### Preconditions\\n\\n- The beneficiary\'s ABHA is linked to their PMJAY card.\\n- The ABDM session token is on `Authorization: Bearer`.\\n- `loginId` is the ABHA number with its hyphens.\\n- A capture device is ready.\\n\\n### Postconditions\\n\\nReturns a `txnId`. Send it with the capture to `Biometric auth verify`.\\n\\n### Common mistakes\\n\\n- Sending the token on `bearer_auth` only, which gets a `401`.\\n- Calling the face host instead of `/hcx/abha/biometric/`.\\n- Stripping the hyphens from `loginId`.\\n- Setting `lr` to `N` when building the capture.\\n\\n### Best practices\\n\\n- Implement fingerprint, iris and face. Each is mandatory, because any one of them may be the only one that works for a given patient.\\n- Set `process` from the stage of the case, not from a constant.\\n- Record the transaction ID, the method and the moment it succeeded against the case.\\n\\n### Related scenario\\n\\nA PMJAY beneficiary arrives for admission. The desk posts this request with `scope` `[\\"ABHA-login\\", \\"Aadhaar-bio-verify\\"]`, `authMode` `FINGERPRINT`, the ABHA number with hyphens, `process` `Preauth` and the scheme payer\'s code, and gets a `txnId` back. The fingerprint is captured on the device and sent with that `txnId` to `Biometric auth verify`.\\n\\n### Specification\\n\\nChapter [Biometric authentication](/docs/nhcx/v1/roles/provider/biometric-authentication) of the NHCX integration specification.","security":[],"headers":[{"name":"process","required":true,"description":"No source puts `process` or `payerid` on `faceauth/init` or `capture/pid`.","example":"Preauth","type":"string"},{"name":"payerid","required":true,"description":"`payerid` is the insurer\'s own participant code. Every insurer has one, even when it works through a TPA.","example":"<payer code>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"scope","type":"string[]","required":false,"description":"","encrypted":false},{"name":"loginHint","type":"string","required":false,"description":"","encrypted":false},{"name":"loginId","type":"string","required":false,"description":"","encrypted":true},{"name":"otpSystem","type":"string","required":false,"description":"","encrypted":false},{"name":"authMode","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"scope":["abha-login","aadhaar-bio-verify"],"loginHint":"abha-number","loginId":"91-XXXX-XXXX-1234","otpSystem":"aadhaar","authMode":"FINGERPRINT"},"responses":[{"status":"200","description":"Returns the `txnId` that `Biometric auth verify` quotes, with a message saying the authentication request was sent.","example":{"txnId":"8c8a12e3-xxxx-4278-xxxx-10acffa44f07","authMode":null,"message":"FingerPrint authentication request successfully sent.","status":null}}],"curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init \\\\\\n  --header \'process: Preauth\' \\\\\\n  --header \'payerid: <payer code>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"scope\\": [\\n    \\"abha-login\\",\\n    \\"aadhaar-bio-verify\\"\\n  ],\\n  \\"loginHint\\": \\"abha-number\\",\\n  \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n  \\"otpSystem\\": \\"aadhaar\\",\\n  \\"authMode\\": \\"FINGERPRINT\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init \\\\\\n  --header \'process: Preauth\' \\\\\\n  --header \'payerid: <payer code>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"scope\\": [\\n    \\"abha-login\\",\\n    \\"aadhaar-bio-verify\\"\\n  ],\\n  \\"loginHint\\": \\"abha-number\\",\\n  \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n  \\"otpSystem\\": \\"aadhaar\\",\\n  \\"authMode\\": \\"FINGERPRINT\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init\\",\\n    headers={\\n        \\"process\\": \\"Preauth\\",\\n        \\"payerid\\": \\"<payer code>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"scope\\": [\\n            \\"abha-login\\",\\n            \\"aadhaar-bio-verify\\"\\n        ],\\n        \\"loginHint\\": \\"abha-number\\",\\n        \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n        \\"otpSystem\\": \\"aadhaar\\",\\n        \\"authMode\\": \\"FINGERPRINT\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"process\\": \\"Preauth\\",\\n    \\"payerid\\": \\"<payer code>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"scope\\": [\\n      \\"abha-login\\",\\n      \\"aadhaar-bio-verify\\"\\n    ],\\n    \\"loginHint\\": \\"abha-number\\",\\n    \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n    \\"otpSystem\\": \\"aadhaar\\",\\n    \\"authMode\\": \\"FINGERPRINT\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init\\"))\\n    .header(\\"process\\", \\"Preauth\\")\\n    .header(\\"payerid\\", \\"<payer code>\\")\\n    .header(\\"Content-Type\\", \\"application/json\\")\\n    .method(\\"POST\\", HttpRequest.BodyPublishers.ofString(\\"\\"\\"\\n        {\\n            \\"scope\\": [\\n                \\"abha-login\\",\\n                \\"aadhaar-bio-verify\\"\\n            ],\\n            \\"loginHint\\": \\"abha-number\\",\\n            \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n            \\"otpSystem\\": \\"aadhaar\\",\\n            \\"authMode\\": \\"FINGERPRINT\\"\\n        }\\n        \\"\\"\\"))\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'POST\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'process: Preauth\',\\n        \'payerid: <payer code>\',\\n        \'Content-Type: application/json\',\\n    ],\\n    CURLOPT_POSTFIELDS => <<<\'JSON\'\\n    {\\n        \\"scope\\": [\\n            \\"abha-login\\",\\n            \\"aadhaar-bio-verify\\"\\n        ],\\n        \\"loginHint\\": \\"abha-number\\",\\n        \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n        \\"otpSystem\\": \\"aadhaar\\",\\n        \\"authMode\\": \\"FINGERPRINT\\"\\n    }\\n    JSON,\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n\\t\\"strings\\"\\n)\\n\\nfunc main() {\\n\\tbody := strings.NewReader(`{\\n  \\"scope\\": [\\n    \\"abha-login\\",\\n    \\"aadhaar-bio-verify\\"\\n  ],\\n  \\"loginHint\\": \\"abha-number\\",\\n  \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n  \\"otpSystem\\": \\"aadhaar\\",\\n  \\"authMode\\": \\"FINGERPRINT\\"\\n}`)\\n\\treq, err := http.NewRequest(\\"POST\\", \\"https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init\\", body)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"process\\", \\"Preauth\\")\\n\\treq.Header.Set(\\"payerid\\", \\"<payer code>\\")\\n\\treq.Header.Set(\\"Content-Type\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"POST\\"), \\"https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init\\");\\nrequest.Headers.TryAddWithoutValidation(\\"process\\", \\"Preauth\\");\\nrequest.Headers.TryAddWithoutValidation(\\"payerid\\", \\"<payer code>\\");\\nrequest.Content = new StringContent(\\"\\"\\"\\n    {\\n        \\"scope\\": [\\n            \\"abha-login\\",\\n            \\"aadhaar-bio-verify\\"\\n        ],\\n        \\"loginHint\\": \\"abha-number\\",\\n        \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n        \\"otpSystem\\": \\"aadhaar\\",\\n        \\"authMode\\": \\"FINGERPRINT\\"\\n    }\\n    \\"\\"\\", System.Text.Encoding.UTF8, \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init\')\\nrequest = Net::HTTP::Post.new(uri)\\nrequest[\'process\'] = \'Preauth\'\\nrequest[\'payerid\'] = \'<payer code>\'\\nrequest[\'Content-Type\'] = \'application/json\'\\nrequest.body = <<~\'JSON\'\\n  {\\n    \\"scope\\": [\\n      \\"abha-login\\",\\n      \\"aadhaar-bio-verify\\"\\n    ],\\n    \\"loginHint\\": \\"abha-number\\",\\n    \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n    \\"otpSystem\\": \\"aadhaar\\",\\n    \\"authMode\\": \\"FINGERPRINT\\"\\n  }\\nJSON\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let h={title:"Submit the biometric auth init",sidebar_label:"Submit the biometric auth init",sidebar_class_name:"api-method api-method--post",description:"Starts a fingerprint or iris authentication of a PMJAY beneficiary against the ABHA registry and returns the txnId the verify call needs.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-biometric.yaml",generated:!0},p,c={},d=[];function u(e){return(0,i.jsx)(s.A,{operation:o})}function l(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}}}]);